use vstd::prelude::*;

verus! {
    fn copy(src: &Vec<i32>, s_start: usize, dest: &Vec<i32>, d_start: usize, len: usize) -> (result: Vec<i32>)
        requires
            src.len() >= s_start + len,
            dest.len() >= d_start + len,
        ensures
            result.len() == dest.len(),
            forall |i: usize| (i < d_start || i >= d_start + len) ==> (result[i] == dest[i]),
            forall |j: usize| (j < len) ==> (result[d_start + j] == src[s_start + j]),
    {
        let mut result = dest.clone(); // Start with a copy of the destination array

        if len == 0 {
            return result; // If length is zero, return the destination array as is
        }

        // Copy elements from src to result
        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
                result.len() == dest.len(),
                forall |k: usize| (k < d_start || k >= d_start + i) ==> (result[k] == dest[k]),
                forall |j: usize| (j < i) ==> (result[d_start + j] == src[s_start + j]),
            decreases len - i,
        {
            result[d_start + i] = src[s_start + i]; // Copy from source to destination
            i = i + 1; // Increment the index
        }

        result // Return the modified result array
    }
}
